  showGate('<div class="su-vfy"><div class="lgh" style="display:flex;flex-direction:column;align-items:center;text-align:center"><div class="lgo">' + LOGO_Q + '</div><h1>' + (nm ? "Almost done, " + esc(nm) : "Check your email") + '</h1><div class="sub">We sent a link to <b>' + esc(u.email) + '</b>. Open it to confirm this email is yours. Check Spam too.</div></div>' +
    '<div class="su-tl"><div class="su-dn"><b>✓</b><span>Account created<small>' + esc(u.email) + '</small></span></div><div class="su-on"><b>2</b><span>Confirm your email<small>Open the link, then press the button below</small></span></div><div><b>3</b><span>Get access<small>The YQI owner sets what you can see. You can chat meanwhile.</small></span></div></div>' +
    '<div class="row" style="flex-direction:column;gap:0"><button id="yqV" style="width:100%;padding:13px;border-radius:12px;font-size:15px;background:linear-gradient(135deg,#4c8a2a,#2F5A1A)">I have confirmed my email</button><div style="display:flex;justify-content:space-between"><button class="g" id="yqR" style="background:none;text-decoration:underline">Send link again</button><button class="g" id="yqO" style="background:none;text-decoration:underline">Sign out</button></div></div><div id="yqMsg" class="msg"></div></div>');
  $("yqV").onclick = function(){ u.reload().then(function(){ if(AUTH.currentUser.emailVerified){ return AUTH.currentUser.getIdToken(true).then(function(){ afterLogin(AUTH.currentUser); }); } msg("Not confirmed yet. Open the link in the email first.", 1); }); };
  $("yqR").onclick = function(){ u.sendEmailVerification().then(function(){ msg("Link sent again."); }).catch(function(e){ msg(errTxt(e), 1); }); };
  $("yqO").onclick = function(){ AUTH.signOut(); };
