  var t = (HCUST ? esc(HCUST) + ' · ' : '') + (U === "d" ? 'by day' : U === "w" ? 'by week' : 'by month') + (U !== "m" || fr ? ' (' + dmy(lo < ks[0] ? ks[0] : lo).slice(0, 5) + ' → ' + dmy(to).slice(0, 5) + ')' : '');
