  var cur = null;
  function place(e){ var w = t.offsetWidth, hh = t.offsetHeight, x = e.clientX + 14, y = e.clientY + 16; if(x + w > innerWidth - 8) x = e.clientX - w - 14; if(y + hh > innerHeight - 8) y = e.clientY - hh - 12; t.style.left = Math.max(6, x) + "px"; t.style.top = Math.max(6, y) + "px"; }
  document.addEventListener("mouseover", function(e){ var el = e.target.closest && e.target.closest("#yqHome [data-tip]"); if(el === cur) return; cur = el; if(!el){ t.style.display = "none"; return; } var s = el.getAttribute("data-tip"); t.innerHTML = esc(s).replace(/^([^\n]*)/, "<b>$1</b>"); t.style.display = "block"; place(e); });
  document.addEventListener("mousemove", function(e){ if(cur) place(e); });
