  var prev = $("yqYC"); if(prev){ prev.__stack = (prev.__stack || 0); } document.body.appendChild(O);
  var done = false, cl = function(){ if(done) return; done = true; O.remove(); };
  try{ YQBACK.push(function(){ cl(); }, "yc"); }catch(e){}
  O.querySelector("[data-yx]").onclick = function(){ try{ if(window.YQBACK && YQBACK.back()) return; }catch(e){} cl(); };
  O.onclick = function(e){ if(e.target === O) O.querySelector("[data-yx]").click(); };
