  if(/not insp|not offer|pending|short/i.test(s)) return "Not Inspected"; if(/reject/i.test(s)) return "Rejected - Quality Issue";
  if(/fail|ng\b|not ok/i.test(s)) return "Failed 1st inspection - awaiting re-inspection";
  if(/pass|ok|accept|approved/i.test(s)) return /re-?insp|2nd|second/i.test(s) ? "Passed - Re-inspection" : "Passed - 1st Go";
