        HMSG = '<span class="hok">Saved ' + Object.keys(cnt).reduce(function(a, k){ return a + cnt[k]; }, 0) + ' articles in ' + Object.keys(plansN).length + ' shipping plans from ' + esc(f.name) + '</span>: ' + Object.keys(cnt).map(function(n){ return esc(n) + ' ' + cnt[n] + (byName[n.toLowerCase()] && byName[n.toLowerCase()].isNew ? ' (new customer added)' : ''); }).join(", ") +
          (err ? ' · <span class="hbad">' + err + ' could not be saved (no edit access)</span>' : '') + (Object.keys(skip).length ? ' · <span class="hbad">skipped, customer not shared with you: ' + Object.keys(skip).map(esc).join(", ") + '</span>' : '') + (bad ? ' · ' + bad + ' rows without a shipping plan skipped' : '') + (noCust ? ' · ' + noCust + ' rows without a customer skipped' : '') + '. The same article uploaded again replaces the old result.';
        lsSet("yqi_lc", ""); HDATA = null; renderHome(); loadHomeTry(0);
