// ---------- free file storage: photos/PDF/Excel kept inside Firestore in 700 KB pieces ----------
var BLOBP = {}, BLOBU = {}, CHUNK = 700000, MAXRAW = 9 * 1024 * 1024;
function wsRoot(){ return FS.collection("ws").doc(WS); }
function b64ToBytes(s){ var bin = atob(s), a = new Uint8Array(bin.length); for(var i = 0; i < bin.length; i++) a[i] = bin.charCodeAt(i); return a; }
